        List<List<T>> out = new ArrayList<>();
        for (List<T> x : a) {
            List<T> y = new ArrayList<>(x);
            Collections.sort(y);
            out.add(y);
        }
        out.sort((p, q) -> cmpList(p, q));
        return out;
    }

